import React, { useState } from 'react';

function VoiceControl() {
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [commands, setCommands] = useState([
    { id: 1, command: 'Turn on the lights', executed: false },
    { id: 2, command: 'Play music', executed: false },
    { id: 3, command: 'Set temperature to 72 degrees', executed: false },
    { id: 4, command: 'Lock the front door', executed: false },
  ]);

  const startListening = () => {
    setIsListening(true);
    // Simulate voice recognition (in real app, this would use Web Speech API)
    setTimeout(() => {
      setIsListening(false);
      setTranscript('Turn on the living room lights');
    }, 3000);
  };

  const stopListening = () => {
    setIsListening(false);
  };

  const executeCommand = (commandId) => {
    setCommands(commands.map(cmd =>
      cmd.id === commandId ? { ...cmd, executed: true } : cmd
    ));

    // Simulate command execution
    setTimeout(() => {
      setCommands(commands.map(cmd =>
        cmd.id === commandId ? { ...cmd, executed: false } : cmd
      ));
    }, 2000);
  };

  return (
    <div className="bg-white min-h-screen py-12">
      <div className="max-w-4xl mx-auto px-4 space-y-8">
        {/* Page Header */}
        <div className="text-center mb-12">
          <h1 className="font-serif text-4xl md:text-5xl font-bold text-secondary mb-4">
            Voice Control Center
          </h1>
          <p className="text-lg text-neutral max-w-2xl mx-auto">
            Experience the power of voice control. Speak naturally and watch your commands come to life.
          </p>
        </div>

        {/* Voice Control Interface */}
        <div className="bg-white rounded-lg shadow-lg border border-gray-100 p-8 md:p-12 text-center">
          {/* Microphone Button */}
          <div className="mb-8">
            <button
              onClick={isListening ? stopListening : startListening}
              className={`w-40 h-40 rounded-full transition-all duration-300 ${isListening
                ? 'bg-red-500 hover:bg-red-600 animate-pulse'
                : 'bg-primary hover:bg-primary/90'
                } text-white font-semibold text-xl shadow-2xl hover:shadow-3xl transform hover:scale-105`}
            >
              <div className="flex flex-col items-center justify-center">
                <span className="text-5xl mb-2">🎤</span>
                <span>{isListening ? 'Listening...' : 'Tap to Speak'}</span>
              </div>
            </button>
          </div>

          {/* Transcript Display */}
          {transcript && (
            <div className="bg-mint rounded-lg p-6 mb-6 border-l-4 border-primary">
              <p className="text-lg text-neutral font-medium">
                You said: <span className="text-primary font-bold">"{transcript}"</span>
              </p>
            </div>
          )}

          {/* Status Indicator */}
          <div className="flex items-center justify-center space-x-3">
            <div className={`w-4 h-4 rounded-full ${isListening ? 'bg-red-500 animate-pulse' : 'bg-green-500'}`}></div>
            <span className={`font-semibold ${isListening ? 'text-red-600' : 'text-green-600'}`}>
              {isListening ? 'Recording in progress...' : 'Ready to listen'}
            </span>
          </div>
        </div>

        {/* Quick Commands */}
        <div className="bg-white rounded-lg shadow-lg border border-gray-100 p-8">
          <h2 className="font-serif text-2xl md:text-3xl font-bold text-secondary mb-6">Quick Commands</h2>
          <p className="text-neutral mb-6">Try these popular voice commands or create your own</p>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {commands.map((command) => (
              <button
                key={command.id}
                onClick={() => executeCommand(command.id)}
                disabled={command.executed}
                className={`p-5 rounded-lg border-2 transition-all font-medium ${command.executed
                  ? 'bg-green-50 border-green-500 text-green-700'
                  : 'border-primary text-primary hover:bg-primary hover:text-white hover:shadow-md'
                  }`}
              >
                <div className="flex items-center justify-between">
                  <span>{command.command}</span>
                  {command.executed && (
                    <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20">
                      <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                    </svg>
                  )}
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Voice Settings */}
        <div className="bg-white rounded-lg shadow-lg border border-gray-100 p-8">
          <h2 className="font-serif text-2xl md:text-3xl font-bold text-secondary mb-6">Voice Settings</h2>
          <div className="space-y-6">
            <div className="flex items-center justify-between p-4 bg-mint rounded-lg">
              <div>
                <span className="font-semibold text-secondary block">Voice Feedback</span>
                <span className="text-sm text-neutral">Hear audio confirmation for commands</span>
              </div>
              <label className="relative inline-flex items-center cursor-pointer">
                <input type="checkbox" className="sr-only peer" defaultChecked />
                <div className="w-14 h-7 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-primary/25 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:rounded-full after:h-6 after:w-6 after:transition-all peer-checked:bg-primary"></div>
              </label>
            </div>

            <div className="flex items-center justify-between p-4 bg-mint rounded-lg">
              <div>
                <span className="font-semibold text-secondary block">Auto-execute commands</span>
                <span className="text-sm text-neutral">Execute commands without confirmation</span>
              </div>
              <label className="relative inline-flex items-center cursor-pointer">
                <input type="checkbox" className="sr-only peer" />
                <div className="w-14 h-7 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-primary/25 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:rounded-full after:h-6 after:w-6 after:transition-all peer-checked:bg-primary"></div>
              </label>
            </div>

            <div className="flex items-center justify-between p-4 bg-mint rounded-lg">
              <div>
                <span className="font-semibold text-secondary block">Wake word detection</span>
                <span className="text-sm text-neutral">Always listen for "Hey Voice"</span>
              </div>
              <label className="relative inline-flex items-center cursor-pointer">
                <input type="checkbox" className="sr-only peer" />
                <div className="w-14 h-7 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-primary/25 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:rounded-full after:h-6 after:w-6 after:transition-all peer-checked:bg-primary"></div>
              </label>
            </div>
          </div>
        </div>

        {/* Tips Section */}
        <div className="bg-mint rounded-lg p-8">
          <h3 className="font-serif text-xl font-bold text-secondary mb-4">💡 Pro Tips</h3>
          <ul className="space-y-3">
            {[
              "Speak clearly and at a normal pace for best results",
              "Use natural language - no need for robotic commands",
              "Try combining multiple actions in one command",
              "Create custom shortcuts for frequently used commands"
            ].map((tip, index) => (
              <li key={index} className="flex items-start space-x-3">
                <svg className="w-6 h-6 text-primary flex-shrink-0 mt-1" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                </svg>
                <span className="text-neutral">{tip}</span>
              </li>
            ))}
          </ul>
        </div>
      </div>
    </div>
  );
}

export default VoiceControl;
